mapper.update:
UPDATE T2000_BOOKMARK

    BOOKMARK_NAME = #{bookmarkName}
    , DEL_YN = #{delYn}
    , UPDATE_DT = SYSDATE

WHERE BOOKMARK_ID = #{bookmarkId}

UPDATE T2000_BOOKMARK_DETAIL

    APPROVER_ID = #{approverId}
    , APPROVER_TYPE_CD = #{approverTypeCd}
    , UPDATE_DT = SYSDATE

WHERE BOOKMARK_ID = #{bookmarkId}
  AND SEQ_NO = #{seqNo}
